import{_ as a,C as e,c as t,o as n,a0 as r,b as i,w as l,a as s,G as o,a1 as d}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Sessionsguide: Introduktion till mentala spel (2–3 timmar)","description":"","frontmatter":{},"headers":[],"relativePath":"sv/mental-journey/session-guide.md","filePath":"sv/mental-journey/session-guide.md"}');const g=a({name:"sv/mental-journey/session-guide.md"},[["render",function(a,u,g,p,k,m){const h=e("Mermaid");return n(),t("div",null,[u[1]||(u[1]=r('<h1 id="sessionsguide-introduktion-till-mentala-spel-2–3-timmar" tabindex="-1">Sessionsguide: Introduktion till mentala spel (2–3 timmar) <a class="header-anchor" href="#sessionsguide-introduktion-till-mentala-spel-2–3-timmar" aria-label="Permalink to &quot;Sessionsguide: Introduktion till mentala spel (2–3 timmar)&quot;">​</a></h1><h2 id="oversikt" tabindex="-1">Översikt <a class="header-anchor" href="#oversikt" aria-label="Permalink to &quot;Översikt&quot;">​</a></h2><p>Den här guiden hjälper dig att genomföra en 2–3 timmar lång introduktionssession i mental spelträning för boulespelare. Perfekt för tränare, klubbledare eller erfarna spelare som vill introducera mental träning till sitt lag.</p><div class="tip custom-block"><p class="custom-block-title">Två avsnitt i den här guiden</p><ul><li><strong><a href="#för-deltagare">För deltagare</a></strong> - Vad spelarna kommer att lära sig</li><li><strong><a href="#för-handledare">För handledare</a></strong> - Hur man genomför sessionen</li></ul></div><h2 id="snabbatkomst" tabindex="-1">Snabbåtkomst <a class="header-anchor" href="#snabbatkomst" aria-label="Permalink to &quot;Snabbåtkomst&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Avsnitt</th><th>Ändamål</th><th>Tillträde</th></tr></thead><tbody><tr><td><strong>För deltagare</strong></td><td>Vad du kan förvänta dig av sessionen</td><td><a href="#för-deltagare">Visa avsnitt</a></td></tr><tr><td><strong>För handledare</strong></td><td>Komplett sessionsplan och tidsplan</td><td><a href="#för-handledare">Visa avsnitt</a></td></tr><tr><td><strong>Material för sessionen</strong></td><td>Guider, bilder och arbetsblad</td><td><a href="/sv/mental-journey/material">Visa material</a></td></tr><tr><td><strong>Förberedelsechecklista</strong></td><td>Vad man ska förbereda inför sessionen</td><td><a href="#förberedelse-1-vecka-innan">Visa checklista</a></td></tr></tbody></table><hr><h2 id="for-deltagare" tabindex="-1">För deltagare <a class="header-anchor" href="#for-deltagare" aria-label="Permalink to &quot;För deltagare&quot;">​</a></h2><h3 id="vad-man-kan-forvanta-sig" tabindex="-1">Vad man kan förvänta sig <a class="header-anchor" href="#vad-man-kan-forvanta-sig" aria-label="Permalink to &quot;Vad man kan förvänta sig&quot;">​</a></h3><p>Den här sessionen introducerar det mentala spelet boule genom diskussioner, övningar och praktiska tekniker som du kan använda direkt.</p><p><strong>Du kommer att lära dig:</strong></p><ul><li>Varför mental träning är viktig för prestation</li><li>Skillnaden mellan &quot;tekniskt läge&quot; och &quot;flödesläge&quot;</li><li>Hur man känner igen och hanterar sin inre kritiker</li><li>Enkla tekniker för tryckhantering</li><li>En grundläggande rutin före skotttagning</li></ul><p><strong>Vad du behöver:</strong></p><ul><li>Öppet sinne och vilja att dela med sig</li><li>Anteckningsbok och penna</li><li>Dina egna erfarenheter att diskutera</li><li>2-3 timmars fokuserad tid</li></ul><h3 id="sessionsstruktur" tabindex="-1">Sessionsstruktur <a class="header-anchor" href="#sessionsstruktur" aria-label="Permalink to &quot;Sessionsstruktur&quot;">​</a></h3>',15)),(n(),i(d,null,{default:l(()=>[o(h,{id:"mermaid-155",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BIntroduktion%20%3Cbr%2F%3E%2020%20minuter%5D%20--%3E%20B%5BZonen%20%3Cbr%2F%3E%2040%20minuter%5D%0A%20%20%20%20B%20--%3E%20C%5BBryta%20%3Cbr%2F%3E%2010%20minuter%5D%0A%20%20%20%20C%20--%3E%20D%5BInre%20kritiker%20%3Cbr%2F%3E%2040%20minuter%5D%0A%20%20%20%20D%20--%3E%20E%5BPraktiska%20verktyg%20%3Cbr%2F%3E%2040%20minuter%5D%0A%20%20%20%20E%20--%3E%20F%5BIntegration%20%3Cbr%2F%3E%2020%20minuter%5D%0A%20%20%20%20%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23f3e5f5%0A%20%20%20%20style%20D%20fill%3A%23ffe4e1%0A%20%20%20%20style%20E%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23c8e6c9%0A"})]),fallback:l(()=>[...u[0]||(u[0]=[s(" Loading... ",-1)])]),_:1})),u[2]||(u[2]=r('<h3 id="viktiga-begrepp-du-kommer-att-utforska" tabindex="-1">Viktiga begrepp du kommer att utforska <a class="header-anchor" href="#viktiga-begrepp-du-kommer-att-utforska" aria-label="Permalink to &quot;Viktiga begrepp du kommer att utforska&quot;">​</a></h3><h4 id="_1-zonen-flodesstatus" tabindex="-1">1. Zonen (flödesstatus) <a class="header-anchor" href="#_1-zonen-flodesstatus" aria-label="Permalink to &quot;1. Zonen (flödesstatus)&quot;">​</a></h4><ul><li>Hur det känns när allt klickar</li><li>Varför tänkande på teknik stör prestationen</li><li>&quot;Övergången&quot; från planering till utförande</li></ul><h4 id="_2-den-inre-kritikern" tabindex="-1">2. Den inre kritikern <a class="header-anchor" href="#_2-den-inre-kritikern" aria-label="Permalink to &quot;2. Den inre kritikern&quot;">​</a></h4><ul><li>Hur negativt självprat påverkar prestationen</li><li>Skillnaden mellan en inre kritiker och en inre coach</li><li>Neutral observation kontra hård bedömning</li></ul><h4 id="_3-tryckrespons" tabindex="-1">3. Tryckrespons <a class="header-anchor" href="#_3-tryckrespons" aria-label="Permalink to &quot;3. Tryckrespons&quot;">​</a></h4><ul><li>Varför du spelar annorlunda i tävling</li><li>Fysiska tecken på tryck</li><li>Snabba återställningstekniker</li></ul><h4 id="_4-praktiska-verktyg" tabindex="-1">4. Praktiska verktyg <a class="header-anchor" href="#_4-praktiska-verktyg" aria-label="Permalink to &quot;4. Praktiska verktyg&quot;">​</a></h4><ul><li>3-andetagsåterställning</li><li>Enkel rutin före skotttagning</li><li>Protokoll för felåterställning</li></ul><h3 id="vad-man-ska-ta-med-sig" tabindex="-1">Vad man ska ta med sig <a class="header-anchor" href="#vad-man-ska-ta-med-sig" aria-label="Permalink to &quot;Vad man ska ta med sig&quot;">​</a></h3><p><strong>Nödvändig:</strong></p><ul><li>Du själv och dina erfarenheter</li><li>Villighet att delta</li></ul><p><strong>Frivillig:</strong></p><ul><li>Exempel på mentala utmaningar du står inför</li><li>Frågor om specifika situationer</li><li>Anteckningsblock för personliga anteckningar</li></ul><h3 id="efter-sessionen" tabindex="-1">Efter sessionen <a class="header-anchor" href="#efter-sessionen" aria-label="Permalink to &quot;Efter sessionen&quot;">​</a></h3><p>Du får:</p><ul><li>Sammanfattning av nyckelbegrepp</li><li>Övningsövningar för veckan</li><li>Länkar till detaljerade utbildningsmoduler</li><li>Målmall för mental spelutveckling</li></ul><hr><h2 id="for-handledare" tabindex="-1">För handledare <a class="header-anchor" href="#for-handledare" aria-label="Permalink to &quot;För handledare&quot;">​</a></h2><h3 id="forberedelsechecklista" tabindex="-1">Förberedelsechecklista <a class="header-anchor" href="#forberedelsechecklista" aria-label="Permalink to &quot;Förberedelsechecklista&quot;">​</a></h3><p><strong>1 vecka innan:</strong></p><ul><li>[ ] Boka rum i 2-3 timmar</li><li>[ ] Bjud in 6–12 deltagare</li><li>[ ] Bokmärk materialsidor (se <a href="/sv/mental-journey/materials">Material</a>)</li><li>[ ] Läs igenom den här guiden noggrant</li><li>[ ] Förbered flipchart eller whiteboard</li></ul><p><strong>1 dag före:</strong></p><ul><li>[ ] Bekräfta närvaro</li><li>[ ] Uppställningsrum (cirkelsittande)</li><li>[ ] Testa all teknik (bilder etc.)</li><li>[ ] Förbered material</li></ul><p><strong>1 timme före:</strong></p><ul><li>[ ] Anländ tidigt</li><li>[ ] Arrangera sittplatser i cirkel</li><li>[ ] Ställ in material</li><li>[ ] Centrera dig själv</li></ul><h3 id="din-roll-som-handledare" tabindex="-1">Din roll som handledare <a class="header-anchor" href="#din-roll-som-handledare" aria-label="Permalink to &quot;Din roll som handledare&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Viktig</p><p>Du är <strong>inte</strong> en terapeut eller teknisk coach. Du är en <strong>handledare</strong> som:</p><ul><li>Guidediskussion</li><li>Skapar tryggt utrymme</li><li>Kopplar samman koncept med upplevelse</li><li>Hanterar gruppdynamik</li></ul></div><p><strong>Nyckelfärdigheter:</strong></p><ul><li>Aktivt lyssnande</li><li>Neutral närvaro</li><li>Att hantera olika personligheter</li><li>Att veta när man ska gå vidare</li></ul><h3 id="detaljerad-sessionsplan" tabindex="-1">Detaljerad sessionsplan <a class="header-anchor" href="#detaljerad-sessionsplan" aria-label="Permalink to &quot;Detaljerad sessionsplan&quot;">​</a></h3><hr><h4 id="del-1-introduktion-20-minuter" tabindex="-1">Del 1: Introduktion (20 minuter) <a class="header-anchor" href="#del-1-introduktion-20-minuter" aria-label="Permalink to &quot;Del 1: Introduktion (20 minuter)&quot;">​</a></h4><p><strong>Mål:</strong></p><ul><li>Skapa psykologisk trygghet</li><li>Sätt förväntningar</li><li>Bygg gruppanslutning</li></ul><p><strong>Manus:</strong></p><p>&quot;Välkomna allihopa. Den här sessionen handlar om det mentala spelet boule – tankarna, känslorna och mönstren som påverkar din prestation.&quot;</p><p><strong>Grundregler:</strong></p><ol><li>Det som delas här stannar här</li><li>Ingen bedömning av andras erfarenheter</li><li>Deltagande är frivilligt</li><li>Det finns inga fel svar</li></ol><p><strong>Snabbrunda:</strong> Namn, hur länge du har spelat, en mental utmaning du står inför.</p><p><strong>Anteckningar till handledaren:</strong></p><ul><li>Gå först till att modellera sårbarhet</li><li>Håll introduktionerna korta (1 minut vardera)</li><li>Lägg märke till vanliga teman</li><li>Validera alla svar</li></ul><hr><h4 id="del-2-zon-flodestillstandet-40-minuter" tabindex="-1">Del 2: Zon-/flödestillståndet (40 minuter) <a class="header-anchor" href="#del-2-zon-flodestillstandet-40-minuter" aria-label="Permalink to &quot;Del 2: Zon-/flödestillståndet (40 minuter)&quot;">​</a></h4><p><strong>Mål:</strong></p><ul><li>Förstå flödestillstånd</li><li>Känna igen tekniskt kontra flödesläge</li><li>Lär dig konceptet &quot;switch&quot;</li></ul><p><strong>Inledande fråga:</strong> &quot;Tänk på en gång när du spelade din bästa boule. Hur kändes det? Vad var annorlunda?&quot;</p><p><strong>Diskussionsfrågor:</strong></p><ol><li>&quot;Hur många av er har haft spel där allt bara klickade?&quot;</li><li>&quot;Vad tänkte du på under de stunderna?&quot;</li><li>&quot;Hur skiljer det sig från när du kämpar?&quot;</li></ol><p><strong>Viktiga undervisningspunkter:</strong></p><p>Använd whiteboardtavlan för att rita:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PLANNING MODE          →    EXECUTION MODE</span></span>\n<span class="line"><span>(Outside circle)            (Inside circle)</span></span>\n<span class="line"><span>- Analyze situation         - Eyes on target</span></span>\n<span class="line"><span>- Choose strategy           - Trust training</span></span>\n<span class="line"><span>- Decide throw type         - Automatic movement</span></span></code></pre></div><p><strong>Övning: Växeln (10 minuter)</strong></p><p>&quot;Låt oss öva på växlingsögonblicket:&quot;</p><ol><li>Stå upp</li><li>Tänk dig att du är utanför cirkeln - tänk på ett skott</li><li>Ta ett andetag</li><li>Gå framåt (in i den imaginära cirkeln)</li><li>Släpp analysen när du kliver framåt</li><li>Fokusera bara på ett imaginärt mål&quot;</li></ol><p><strong>Avrapportering:</strong></p><ul><li>&quot;Vad lade du märke till?&quot;</li><li>&quot;Var det lätt eller svårt att släppa taget om tankarna?&quot;</li><li>&quot;Hur kan detta gälla i riktiga spel?&quot;</li></ul><hr><h4 id="del-3-paus-10-minuter" tabindex="-1">Del 3: Paus (10 minuter) <a class="header-anchor" href="#del-3-paus-10-minuter" aria-label="Permalink to &quot;Del 3: Paus (10 minuter)&quot;">​</a></h4><p><strong>Handledarens åtgärder:</strong></p><ul><li>Uppmuntra informell diskussion</li><li>Lägg märke till gruppenergi</li><li>Förbered dig för nästa avsnitt</li></ul><hr><h4 id="del-4-den-inre-kritikern-40-minuter" tabindex="-1">Del 4: Den inre kritikern (40 minuter) <a class="header-anchor" href="#del-4-den-inre-kritikern-40-minuter" aria-label="Permalink to &quot;Del 4: Den inre kritikern (40 minuter)&quot;">​</a></h4><p><strong>Mål:</strong></p><ul><li>Känna igen negativa självpratmönster</li><li>Skilj på inre kritiker från inre coach</li><li>Öva neutral observation</li></ul><p><strong>Öppning:</strong> &quot;Vi har alla en inre röst som kommenterar våra prestationer. Ibland är det hjälpsamt, ibland är det hårt. Låt oss utforska det.&quot;</p><p><strong>Övning: Inre kritikerinventering (15 minuter)</strong></p><p>&quot;Skriv ner på ditt papper:</p><ol><li>Vad din inre röst säger efter ett dåligt kast</li><li>Vad det säger när du är under press</li><li>Vad det säger om dina förmågor&quot;</li></ol><p><em>Ge 5 minuter för skrivandet</em></p><p>&quot;Nå, vem är villig att dela med sig av ett exempel?&quot;</p><p><strong>Anteckningar till handledaren:</strong></p><ul><li>Normalisera hårt självprat</li><li>Försök inte &quot;fixa&quot; någon</li><li>Leta efter vanliga mönster</li></ul><p><strong>Undervisning: Inre kritiker vs. Inre coach (15 minuter)</strong></p><p>Rita två kolumner på whiteboardtavlan:</p><table tabindex="0"><thead><tr><th>Inre kritiker</th><th>Inre tränare</th></tr></thead><tbody><tr><td>&quot;Hur kunde du missa det?!&quot;</td><td>&quot;Det gick åt vänster&quot;</td></tr><tr><td>&quot;Du kvävs alltid&quot;</td><td>&quot;Vi försöker igen&quot;</td></tr><tr><td>&quot;Du är hemsk&quot;</td><td>&quot;Vad kan jag lära mig?&quot;</td></tr></tbody></table><p><strong>Diskussion:</strong></p><ul><li>&quot;Märker du skillnaden?&quot;</li><li>&quot;Vilken röst hjälper framträdandet?&quot;</li><li>&quot;Kan du ändra rösten?&quot;</li></ul><p><strong>Övning: Omformulering (10 minuter)</strong></p><p>&quot;Ta ett av dina uttalanden från den inre kritikern. Hur skulle en inre coach uttrycka det?&quot;</p><p>Dela exempel.</p><hr><h4 id="del-5-praktiska-verktyg-40-minuter" tabindex="-1">Del 5: Praktiska verktyg (40 minuter) <a class="header-anchor" href="#del-5-praktiska-verktyg-40-minuter" aria-label="Permalink to &quot;Del 5: Praktiska verktyg (40 minuter)&quot;">​</a></h4><p><strong>Mål:</strong></p><ul><li>Lär dig 3-andetagsåterställning</li><li>Skapa en enkel rutin före skotttagning</li><li>Förstå felåterställning</li></ul><p><strong>Verktyg 1: Återställning av 3 andetag (10 minuter)</strong></p><p>&quot;Det här är din nödåterställningsknapp. Använd den när du känner att trycket ökar.&quot;</p><p><strong>Demonstrera:</strong></p><ol><li>Andas in i 4 räkningar</li><li>Håll i 2 räkningar</li><li>Andas ut i 6 räkningar</li><li>Upprepa 3 gånger</li></ol><p>&quot;Låt oss öva tillsammans nu.&quot;</p><p><em>Leda gruppen genom 3 cykler</em></p><p><strong>Avrapportering:</strong></p><ul><li>&quot;Vad märkte du i din kropp?&quot;</li><li>&quot;När kan du använda detta?&quot;</li></ul><p><strong>Verktyg 2: Enkel rutin före fotografering (15 minuter)</strong></p><p>&quot;En rutin hjälper dig att konsekvent växla från planering till genomförande.&quot;</p><p><strong>Grundläggande struktur:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Outside Circle (Planning):</span></span>\n<span class="line"><span>- Look at situation</span></span>\n<span class="line"><span>- Decide on throw</span></span>\n<span class="line"><span>- See the result in your mind</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Walking to Circle (Transition):</span></span>\n<span class="line"><span>- One deep breath</span></span>\n<span class="line"><span>- Let go of analysis</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Inside Circle (Execution):</span></span>\n<span class="line"><span>- Eyes on target only</span></span>\n<span class="line"><span>- Trust your training</span></span>\n<span class="line"><span>- Execute</span></span></code></pre></div><p><strong>Utöva:</strong> &quot;Skapa din egen 3-stegsrutin. Skriv ner den.&quot;</p><p>Dela exempel.</p><p><strong>Verktyg 3: Protokoll för felsökning (15 minuter)</strong></p><p>&quot;Elitspelare gör inte färre misstag. De återhämtar sig snabbare.&quot;</p><p><strong>3-stegsprotokoll:</strong></p><ol><li><strong>Observera</strong> - Ange faktum neutralt (&quot;Det gick åt vänster&quot;)</li><li><strong>Lär dig</strong> - Extrahera information (&quot;Vinden är starkare än jag trodde&quot;)</li><li><strong>Återställning</strong> - Gå framåt (3-andetagsåterställning, blicken framåt)</li></ol><p><strong>Öva:</strong> &quot;Tänk på ett misstag du nyligen begick. Gå igenom de tre stegen.&quot;</p><hr><h4 id="del-6-integration-och-avslutning-20-minuter" tabindex="-1">Del 6: Integration och avslutning (20 minuter) <a class="header-anchor" href="#del-6-integration-och-avslutning-20-minuter" aria-label="Permalink to &quot;Del 6: Integration och avslutning (20 minuter)&quot;">​</a></h4><p><strong>Mål:</strong></p><ul><li>Konsolidera lärandet</li><li>Skapa handlingsplaner</li><li>Tillhandahåll resurser</li></ul><p><strong>Reflektionsfrågor:</strong></p><ol><li>&quot;Vilken insikt tar du med dig?&quot;</li><li>&quot;Vad är en sak du ska prova den här veckan?&quot;</li><li>&quot;Vilka frågor återstår?&quot;</li></ol><p><strong>Handlingsplanering (10 minuter)</strong></p><p>&quot;På ditt utdelningsblad, skriv:</p><ol><li>En teknik du ska öva på den här veckan</li><li>När/var du ska öva på det</li><li>Hur du kommer att följa dina framsteg&quot;</li></ol><p><strong>Resurser:</strong></p><ul><li>Dela ut sammanfattningsblad</li><li>Dela webbplatsen: carreau.app</li><li>Rekommenderad startmodul: <a href="/sv/utbildning/zonen/">Zonen</a></li></ul><p><strong>Slutningscirkel:</strong> &quot;Ett ord som beskriver hur du känner dig just nu.&quot;</p><p><strong>Slutord:</strong> &quot;Mental träning är en färdighet som alla andra – det kräver övning. Börja i liten skala, ha tålamod med dig själv och lägg märke till vad som förändras. Tack för din öppenhet idag.&quot;</p><hr><h3 id="tips-for-handledare" tabindex="-1">Tips för handledare <a class="header-anchor" href="#tips-for-handledare" aria-label="Permalink to &quot;Tips för handledare&quot;">​</a></h3><h4 id="hantera-svara-situationer" tabindex="-1">Hantera svåra situationer <a class="header-anchor" href="#hantera-svara-situationer" aria-label="Permalink to &quot;Hantera svåra situationer&quot;">​</a></h4><p><strong>Om någon dominerar:</strong></p><ul><li>&quot;Tack [namn]. Låt oss höra från andra.&quot;</li><li>Använd strukturerad turtagning</li></ul><p><strong>Om någon är motståndskraftig:</strong></p><ul><li>Argumentera inte</li><li>&quot;Det är ett giltigt perspektiv. Vad tycker andra?&quot;</li><li>Anpassa sig till deras oro</li></ul><p><strong>Om någon blir känslosam:</strong></p><ul><li>Normalisera det</li><li>&quot;Det här berör något verkligt. Tack för att du delar med dig.&quot;</li><li>Försök inte att fixa</li></ul><p><strong>Om diskussionen stannar av:</strong></p><ul><li>Använd specifika uppmaningar</li><li>Dela ditt eget exempel</li><li>Gå till en övning</li></ul><h4 id="energihantering" tabindex="-1">Energihantering <a class="header-anchor" href="#energihantering" aria-label="Permalink to &quot;Energihantering&quot;">​</a></h4><p><strong>Hög energi:</strong> Använd övningar och rörelse <strong>Låg energi:</strong> Ställ provocerande frågor <strong>Spridda:</strong> Återställ till strukturen <strong>Spänt:</strong> Använd humor eller paus</p><h3 id="efter-sessionen-1" tabindex="-1">Efter sessionen <a class="header-anchor" href="#efter-sessionen-1" aria-label="Permalink to &quot;Efter sessionen&quot;">​</a></h3><p><strong>Uppföljning:</strong></p><ul><li>Skicka sammanfattningsmejl inom 24 timmar</li><li>Inkludera länkar till resurser</li><li>Erbjud dig att svara på frågor</li><li>Schemalägg valfri uppföljningssession</li></ul><p><strong>Självreflektion:</strong></p><ul><li>Vad fungerade bra?</li><li>Vad skulle du ändra?</li><li>Vad överraskade dig?</li><li>Vad lärde du dig?</li></ul><hr><h2 id="material" tabindex="-1">Material <a class="header-anchor" href="#material" aria-label="Permalink to &quot;Material&quot;">​</a></h2><ul><li><a href="/sv/mental-resa/material#deltagarguide">Deltagarguide</a></li><li><a href="/sv/mental-journey/material#handledarens-bilder">Handledarens bilder</a></li><li><a href="/sv/mental-resa/material#sammanfattningsblad">Sammanfattningsblad</a></li><li><a href="/sv/mental-resa/material#övningsblad">Övningsblad</a></li></ul><hr><div class="tip custom-block"><p class="custom-block-title">Redo att underlätta?</p><ol><li>Läs igenom den här guiden noggrant</li><li>Ladda ner material</li><li>Öva på övningarna själv</li><li>Schemalägg din session</li><li>Lita på processen</li></ol></div>',140))])}]]);export{u as __pageData,g as default};
